+/// Two keyed FNV-1a hashes of `slice` computed in one pass over the bytes.
+fn slice_hash_pair(slice: &[u8], first: u64, second: u64) -> (u64, u64) {
+    let (mut a, mut b) = (first, second);
+    let mut chunks = slice.chunks_exact(8);
+    for chunk in &mut chunks {
+        let chunk: &[u8; 8] = chunk.try_into().unwrap();
+        for &byte in chunk {
+            let byte = u64::from(byte);
+            a = (a ^ byte).wrapping_mul(FNV_PRIME);
+            b = (b ^ byte).wrapping_mul(FNV_PRIME);
+        }
+    }
+    for &byte in chunks.remainder() {
+        let byte = u64::from(byte);
+        a = (a ^ byte).wrapping_mul(FNV_PRIME);
+        b = (b ^ byte).wrapping_mul(FNV_PRIME);
+    }
+    (a, b)
+}
+
+impl<T: AsRef<[u8]>> BloomHashIndex for T {
+    fn hash_at_index(&self, hash_index: u64) -> u64 {
+        slice_hash(self.as_ref(), hash_index)
+    }
+    fn hash_at_index_pair(&self, first: u64, second: u64) -> (u64, u64) {
+        slice_hash_pair(self.as_ref(), first, second)
+    }
+}

